$completedSessionId=null; $accessKey=null; $result=record('api.sessions.get-result',function()use($sessions,$createDirect,&$completedSessionId,&$accessKey){$completed=$createDirect(); $completedSessionId=value($completed,'sessionId'); [$token,$accessKey]=completedRedirectSession($completed); return invoke($sessions,'getSessionResult',[$completedSessionId,model('GetSessionResultRequest',['redirect_token'=>$token,'results_access_key'=>$accessKey])]);});
